  bet: string;
  line: string;
  stat: string;
  type: 'MORE' | 'LESS';
  odds: string;
  probability: string;
  ev?: number;
  isElite179?: boolean;
  analysis?: string;
  situationalNote?: string;
  matchupMetric?: MatchupMetric;
