                                <div className="flex-1">
                                    <div className="flex items-center gap-2">
                                        <span className="text-xl font-black text-white uppercase italic">{prop.player}</span>
                                        {prop.isElite179 && <span className="w-2 h-2 bg-amber-500 rounded-full animate-pulse" title="High Fidelity Signal"></span>}
                                    </div>
                                    <div className="flex items-center gap-4 mt-2">
                                        <span className={`text-[10px] font-black px-3 py-1 rounded-lg border uppercase ${prop.type === 'MORE' ? 'bg-green-500/20 text-green-400 border-green-500/20' : 'bg-red-500/20 text-red-400 border-red-500/20'}`}>{prop.type === 'MORE' ? 'OVER' : 'UNDER'}</span>
                                        <span className="text-3xl font-black text-white tabular-nums">{prop.line}</span>
                                        <span className="text-[10px] font-black text-zinc-600 uppercase tracking-widest">{prop.stat}</span>
                                    </div>
                                </div>
                                <button onClick={() => onTogglePick && onTogglePick(prop)} className={`w-14 h-14 rounded-2xl flex items-center justify-center transition-all ${isInSlip ? 'bg-amber-500 text-black shadow-lg shadow-amber-500/30' : 'bg-zinc-900 text-zinc-600 hover:border-zinc-700'}`}>
                                    {isInSlip ? <CheckIcon className="w-7 h-7" /> : <PlusIcon className="w-7 h-7" />}
                                </button>
                            </div>

                            {prop.situationalNote && (
                                <div className="mt-4 bg-zinc-900/40 border border-white/5 p-3 rounded-xl">
                                    <p className="text-[10px] text-zinc-500 leading-relaxed italic">
                                        <span className="text-amber-500 font-black uppercase text-[8px] mr-2">Deep Logic:</span>
                                        {prop.situationalNote}
                                    </p>
                                </div>
                            )}

                            <div className="mt-5 flex items-center gap-4">
                                <div className="flex-1 h-1 bg-zinc-900 rounded-full overflow-hidden">
                                    <div className={`h-full ${probInt >= 70 ? 'bg-green-500' : 'bg-amber-500'}`} style={{ width: prop.probability }}></div>
                                </div>
                                <div className="text-[9px] font-black text-zinc-600 uppercase tabular-nums">{prop.probability} HIT CONFIDENCE</div>
                            </div>
                        </div>
                    );
                })}
            </div>
       </div>
    </div>
  );
});

import React, { memo, useState, useMemo } from 'react';
import type { Prediction, OddsFormat, PropBet } from '../types';
import { AnalyticsIcon, PlusIcon, CheckIcon, LogoIcon } from './Icons';

interface PredictionDisplayProps {
  prediction: Prediction;
  oddsFormat: OddsFormat;
  onAnalyzeProp?: (prop: PropBet) => void;
  pickSlip?: PropBet[];
  onTogglePick?: (prop: PropBet) => void;
  onSearchPlayer?: (player: string) => void;
}

const confidenceStyles: Record<string, { bg: string; text: string; border: string; accent: string; glow: string }> = {
    High: { bg: 'bg-green-950/20', text: 'text-green-400', border: 'border-green-500/30', accent: 'bg-green-500', glow: 'shadow-[0_0_30px_rgba(34,197,94,0.2)]' },
    Medium: { bg: 'bg-amber-950/20', text: 'text-amber-400', border: 'border-amber-500/30', accent: 'bg-amber-500', glow: 'shadow-[0_0_30px_rgba(245,158,11,0.2)]' },
    Low: { bg: 'bg-zinc-900/40', text: 'text-zinc-400', border: 'border-zinc-800', accent: 'bg-zinc-600', glow: 'shadow-none' },
};

export const PredictionDisplay: React.FC<PredictionDisplayProps> = memo(({ prediction, pickSlip = [], onTogglePick }) => {
  const [typeFilter, setTypeFilter] = useState<'All' | 'MORE' | 'LESS'>('All');

  const confidenceStyle = confidenceStyles[prediction.confidence] || confidenceStyles['Medium'];

  // Ensure the score is between 0 and 1 before multiplying, just in case the model returns 0-100 directly
  const rawScore = prediction.confidenceScore > 1 ? prediction.confidenceScore / 100 : prediction.confidenceScore;
  const probVal = prediction.confidenceScore != null ? Math.round(rawScore * 100) : 0;

  // Circumference for r=56 is ~351.85
  const circumference = 351.85;

  const filteredProps = useMemo(() => {
    if (!prediction.props) return [];
    return [...prediction.props]
      .filter(prop => typeFilter === 'All' || prop.type === typeFilter)
      .sort((a, b) => (parseInt(b.probability) || 0) - (parseInt(a.probability) || 0));
  }, [prediction.props, typeFilter]);

  return (
    <div className="space-y-6 w-full animate-fade-in pb-10">

       {/* High-Fidelity Roster & Situational Context */}
       <div className="grid md:grid-cols-2 gap-4">
            {prediction.situationalIntelligence && (
                <div className={`rounded-3xl p-5 border bg-zinc-950/80 ${prediction.situationalIntelligence.isHighStakes ? 'border-amber-500/30' : 'border-zinc-800'}`}>
                    <div className="flex items-center gap-3 mb-4">
                        <div className="bg-amber-500/10 p-2 rounded-xl border border-amber-500/20 text-amber-500">
                            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17.657 16.657L13.414 20.9a1.998 1.998 0 01-2.827 0l-4.244-4.243a8 8 0 1111.314 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 11a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
                        </div>
                        <div>
                            <h4 className="text-[10px] font-black uppercase tracking-[0.2em] text-zinc-500">Venue & Context</h4>
                            <span className="text-xs font-black text-white uppercase">{prediction.situationalIntelligence.motivationLevel}</span>
                        </div>
                    </div>
                    <p className="text-[11px] text-zinc-400 italic leading-relaxed">
                        {prediction.situationalIntelligence.leverageAnalysis}
                    </p>
                    {prediction.situationalIntelligence.weatherImpact && (
                        <div className="mt-3 flex items-center gap-2">
                             <span className="text-[8px] font-black px-2 py-0.5 rounded bg-blue-500/10 text-blue-400 border border-blue-500/20 uppercase">Weather Factor: {prediction.situationalIntelligence.weatherImpact}</span>
                        </div>
                    )}
                </div>
            )}

            {prediction.injuryReport && (
                 <div className="rounded-3xl p-5 border border-red-500/20 bg-zinc-950/80">
                    <div className="flex items-center gap-3 mb-4">
                        <div className="bg-red-500/10 p-2 rounded-xl border border-red-500/20 text-red-500">
                             <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
                        </div>
                        <h4 className="text-[10px] font-black uppercase tracking-[0.2em] text-red-500">Roster Scrub</h4>
                    </div>
                    <div className="space-y-2">
                        {prediction.injuryReport.slice(0, 3).map((injury, i) => (
                            <div key={i} className="flex justify-between items-center bg-black/40 p-2 rounded-lg border border-white/5">
                                <div className="flex flex-col">
                                    <span className="text-[10px] font-black text-white">{injury.player}</span>
                                    <span className="text-[8px] text-zinc-500 font-bold uppercase">{injury.role} • {injury.status}</span>
                                </div>
                                <div className={`text-[10px] font-black ${injury.impactScore > 7 ? 'text-red-500' : 'text-zinc-500'}`}>-{injury.impactScore}</div>
                            </div>
                        ))}
                    </div>
                 </div>
            )}
       </div>

       {/* Confidence & Calibration Breakdown */}
       <div className="bg-zinc-950 rounded-3xl border border-white/5 overflow-hidden">
            <div className="p-6 border-b border-white/5 flex flex-col md:flex-row gap-6 justify-between items-start">
                <div className="flex-1 space-y-4">
                    <div className="flex items-center gap-3">
                         <LogoIcon className="w-5 h-5 text-amber-500" />
                         <h3 className="text-xs font-black text-white uppercase tracking-[0.3em]">Accuracy Calibration</h3>
                    </div>
                    <p className="text-[11px] text-zinc-400 italic leading-relaxed">
                        {prediction.confidenceReasoning}
                    </p>
                    <div className="grid grid-cols-3 gap-2">
                         <div className="bg-black/40 p-2 rounded-xl border border-white/5 text-center">
                            <span className="text-[7px] font-black text-zinc-600 uppercase block mb-1">Roster Stability</span>
                            <span className={`text-[10px] font-black ${prediction.calibrationMetrics.rosterStability > 80 ? 'text-green-500' : 'text-amber-500'}`}>{prediction.calibrationMetrics.rosterStability}%</span>
                         </div>
                         <div className="bg-black/40 p-2 rounded-xl border border-white/5 text-center">
                            <span className="text-[7px] font-black text-zinc-600 uppercase block mb-1">Market Align</span>
                            <span className="text-[10px] font-black text-white">{prediction.calibrationMetrics.marketAlignment}%</span>
                         </div>
                         <div className="bg-black/40 p-2 rounded-xl border border-white/5 text-center">
                            <span className="text-[7px] font-black text-zinc-600 uppercase block mb-1">Variance Risk</span>
                            <span className={`text-[10px] font-black ${prediction.calibrationMetrics.varianceRisk === 'High' ? 'text-red-500' : 'text-green-500'}`}>{prediction.calibrationMetrics.varianceRisk}</span>
                         </div>
                    </div>
                </div>
                <div 
                  className="relative flex items-center justify-center w-32 h-32 cursor-help group/meter"
                  title={`Exact Confidence Score: ${prediction.confidenceScore.toFixed(4)}`}
                >
                    <svg className="w-full h-full transform -rotate-90">
                        <circle cx="64" cy="64" r="56" stroke="currentColor" strokeWidth="10" fill="transparent" className="text-zinc-900" />
                        <circle 
                          cx="64" 
                          cy="64" 
                          r="56" 
                          stroke="currentColor" 
                          strokeWidth="10" 
                          fill="transparent" 
                          strokeDasharray={circumference} 
                          strokeDashoffset={circumference - (circumference * probVal) / 100} 
                          className={`${confidenceStyle.text} transition-all duration-1000 ease-out`} 
                        />
                    </svg>
                    <div className="absolute inset-0 flex flex-col items-center justify-center transition-transform group-hover/meter:scale-110">
                        <span className="text-2xl font-black text-white tabular-nums tracking-tighter">{probVal}%</span>
                        <span className="text-[7px] font-black text-zinc-500 uppercase tracking-widest">{prediction.confidence}</span>
                    </div>
                    {/* Visual hint for the tooltip */}
                    <div className="absolute -bottom-1 text-[6px] font-bold text-zinc-700 opacity-0 group-hover/meter:opacity-100 transition-opacity uppercase">
                      Deep Score Audit
                    </div>
                </div>
            </div>
       </div>

       {/* Advanced Analytics Grid */}
       {prediction.advancedAnalytics && (
           <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
               {prediction.advancedAnalytics.map((metric, i) => (
                   <div key={i} className="bg-zinc-900/40 border border-zinc-800 p-3 rounded-2xl flex flex-col items-center text-center group hover:bg-zinc-800/60 transition-colors">
                        <span className="text-[8px] font-black text-zinc-500 uppercase tracking-widest mb-1">{metric.label}</span>
                        <span className="text-xl font-black text-amber-500 tracking-tighter">{metric.value}</span>
                        <div className="w-full h-1 bg-zinc-800 rounded-full mt-2 overflow-hidden">
                             <div className="h-full bg-amber-500/50" style={{ width: `${metric.percentile}%` }}></div>
                        </div>
                        <span className="text-[7px] text-zinc-600 font-bold uppercase mt-1">{metric.description}</span>
                   </div>
               ))}
           </div>
       )}

       {/* Primary Engine Result */}
       <div className={`p-8 rounded-[2.5rem] border ${confidenceStyle.border} ${confidenceStyle.bg} backdrop-blur-3xl shadow-2xl relative overflow-hidden group`}>
          <div className="absolute top-0 right-0 p-8 opacity-[0.03] group-hover:opacity-[0.08] transition-opacity pointer-events-none">
                <AnalyticsIcon className="w-48 h-48 text-white" />
          </div>
          <div className="flex flex-col md:flex-row justify-between items-center gap-10 relative z-10">
             <div className="flex items-center gap-8">
                 <div className="relative">
                    <img src={`https://avatar.vercel.sh/${encodeURIComponent(prediction.winner)}.png?size=160`} className={`w-28 h-28 rounded-full border-4 ${confidenceStyle.border} relative z-10 shadow-2xl`} />
                    {prediction.eliteSignal179 && (
                         <div className="absolute -top-2 -right-2 bg-amber-500 text-black px-2 py-0.5 rounded font-black text-[8px] uppercase tracking-widest z-20 shadow-lg animate-bounce">Elite Signal</div>
                    )}
                 </div>
                 <div className="space-y-1">
                    <span className="text-[10px] font-black uppercase tracking-[0.4em] text-zinc-500 block mb-2">Primary Simulation Verdict</span>
                    <h2 className="text-4xl md:text-5xl font-black text-white leading-none tracking-tighter uppercase italic">{prediction.winner}</h2>
                 </div>
             </div>
          </div>
          <div className="mt-10 pt-8 border-t border-white/5">
              <p className="text-zinc-200 text-base md:text-lg leading-relaxed font-medium italic opacity-90">
                "{prediction.analysis}"
              </p>
          </div>
       </div>

       {/* Prop Market Breakdown */}
       <div className="space-y-6">
            <div className="flex justify-between items-end px-2">
                <h3 className="text-[11px] font-black text-zinc-500 uppercase tracking-[0.4em]">High Fidelity Analytics Props</h3>
                <div className="flex gap-2">
                    {['All', 'MORE', 'LESS'].map(f => (
                        <button key={f} onClick={() => setTypeFilter(f as any)} className={`px-3 py-1 text-[9px] font-black rounded-full border transition-all ${typeFilter === f ? 'bg-amber-500 text-black border-amber-400' : 'bg-zinc-900 text-zinc-500 border-zinc-800'}`}>{f}</button>
                    ))}
                </div>
            </div>
            <div className="grid gap-4">
                {filteredProps.map((prop, index) => {
                    const isInSlip = pickSlip.some(p => p.player === prop.player && p.stat === prop.stat);
                    const probInt = parseInt(prop.probability) || 0;
                    return (
                        <div key={index} className={`relative bg-zinc-950/80 rounded-[2rem] border transition-all duration-500 p-6 ${isInSlip ? 'border-amber-500/50 bg-amber-500/[0.02]' : 'border-zinc-900 hover:border-zinc-800'}`}>
                            <div className="flex items-center gap-6">
                                <img src={`https://avatar.vercel.sh/${encodeURIComponent(prop.player)}.png?size=80`} className="w-16 h-16 rounded-full border-2 border-zinc-900 bg-zinc-950 shadow-xl" />
                                <div className="flex-1">
                                    <div className="flex items-center gap-2">
                                        <span className="text-xl font-black text-white uppercase italic">{prop.player}</span>
                                        {prop.isElite179 && <span className="w-2 h-2 bg-amber-500 rounded-full animate-pulse" title="High Fidelity Signal"></span>}
                                    </div>
                                    <div className="flex items-center gap-4 mt-2">
                                        <span className={`text-[10px] font-black px-3 py-1 rounded-lg border uppercase ${prop.type === 'MORE' ? 'bg-green-500/20 text-green-400 border-green-500/20' : 'bg-red-500/20 text-red-400 border-red-500/20'}`}>{prop.type === 'MORE' ? 'OVER' : 'UNDER'}</span>
                                        <span className="text-3xl font-black text-white tabular-nums">{prop.line}</span>
                                        <span className="text-[10px] font-black text-zinc-600 uppercase tracking-widest">{prop.stat}</span>
                                    </div>
                                </div>
                                <button onClick={() => onTogglePick && onTogglePick(prop)} className={`w-14 h-14 rounded-2xl flex items-center justify-center transition-all ${isInSlip ? 'bg-amber-500 text-black shadow-lg shadow-amber-500/30' : 'bg-zinc-900 text-zinc-600 hover:border-zinc-700'}`}>
                                    {isInSlip ? <CheckIcon className="w-7 h-7" /> : <PlusIcon className="w-7 h-7" />}
                                </button>
                            </div>

                            {prop.situationalNote && (
                                <div className="mt-4 bg-zinc-900/40 border border-white/5 p-3 rounded-xl">
                                    <p className="text-[10px] text-zinc-500 leading-relaxed italic">
                                        <span className="text-amber-500 font-black uppercase text-[8px] mr-2">Deep Logic:</span>
                                        {prop.situationalNote}
                                    </p>
                                </div>
                            )}

                            <div className="mt-5 flex items-center gap-4">
                                <div className="flex-1 h-1 bg-zinc-900 rounded-full overflow-hidden">
                                    <div className={`h-full ${probInt >= 70 ? 'bg-green-500' : 'bg-amber-500'}`} style={{ width: prop.probability }}></div>
                                </div>
                                <div className="text-[9px] font-black text-zinc-600 uppercase tabular-nums">{prop.probability} HIT CONFIDENCE</div>
                            </div>
                        </div>
                    );
                })}
            </div>
       </div>
    </div>
  );
});
